from __future__ import annotations

import dataclasses
from typing import Iterable


@dataclasses.dataclass(frozen=True)
class RoutingDecision:
    role: str
    reason: str
    requires_handoff: bool = False


DISCOVERY_STAGES = {"discovery", "search", "inventory", "test", "small-edit"}
HEAVY_STAGES = {"architecture", "review", "hard-debug", "escalation"}
IMPLEMENTATION_STAGES = {"implementation", "coding", "refactor"}


def _clean_paths(paths: Iterable[str] | None) -> list[str]:
    return [str(path).strip() for path in (paths or []) if str(path).strip()]


def route_task(
    *,
    stage: str = "discovery",
    target_paths: Iterable[str] | None = None,
    failures: int = 0,
    complexity: str = "normal",
    explicit_role: str | None = None,
) -> RoutingDecision:
    """Choose a role without letting the 30B model become a free repository scout.

    The routing deliberately starts cheap. The 30B main coder is only selected
    once a handoff has narrowed the work to concrete paths. The 27B heavy model
    is reserved for architecture/review or escalation after failed attempts.
    """

    if explicit_role:
        role = explicit_role.strip().lower()
        if role not in {"fast", "main", "heavy"}:
            raise ValueError(f"Unbekannte Modellrolle: {explicit_role}")
        if role == "main" and not _clean_paths(target_paths):
            raise ValueError("Die Rolle 'main' benötigt mindestens einen target_path im Handoff.")
        return RoutingDecision(role, "Rolle wurde explizit angefordert.", role == "main")

    normalized_stage = str(stage or "discovery").strip().lower()
    normalized_complexity = str(complexity or "normal").strip().lower()
    paths = _clean_paths(target_paths)
    failures = max(0, int(failures))

    if normalized_stage in HEAVY_STAGES or failures >= 2:
        return RoutingDecision(
            "heavy",
            "Architektur/Review oder wiederholte Fehlschläge benötigen das stärkste Analysemodell.",
        )

    if not paths:
        if failures >= 1 and normalized_complexity in {"high", "complex", "hard"}:
            return RoutingDecision(
                "heavy",
                "FastCoder konnte bei komplexer Aufgabe keinen belastbaren Zielpfad bestimmen.",
            )
        return RoutingDecision(
            "fast",
            "Noch kein belastbarer Zielpfad vorhanden; zuerst Bestand und relevante Dateien eingrenzen.",
        )

    if normalized_stage in IMPLEMENTATION_STAGES or normalized_complexity in {"high", "complex", "hard"}:
        return RoutingDecision(
            "main",
            "Konkrete Zielpfade liegen vor; die Implementierung kann gezielt an den 30B-Coder übergeben werden.",
            True,
        )

    if normalized_stage in DISCOVERY_STAGES:
        return RoutingDecision(
            "fast",
            "Suche, Tests oder kleine Änderungen bleiben beim FastCoder.",
        )

    return RoutingDecision(
        "fast",
        "Standardmäßig beginnt der FastCoder; größere Modelle werden nur bei klarer Übergabe oder Eskalation geladen.",
    )


def validate_handoff(role: str, handoff: dict) -> None:
    role = str(role).strip().lower()
    if not isinstance(handoff, dict):
        raise ValueError("handoff muss ein JSON-Objekt sein.")
    if not str(handoff.get("task", "")).strip():
        raise ValueError("handoff.task fehlt.")
    paths = _clean_paths(handoff.get("target_paths"))
    if len(paths) > 12:
        raise ValueError("Handoff enthält mehr als 12 Zielpfade; vor Übergabe weiter eingrenzen.")
    if role == "main" and not paths:
        raise ValueError("Der 30B-Main-Coder darf nicht ohne konkrete target_paths gestartet werden.")

from __future__ import annotations

import argparse
import dataclasses
import json
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any, Callable


DEFAULT_PROFILES = Path(__file__).with_name("profiles.json")


@dataclasses.dataclass(frozen=True)
class ModelProfile:
    role: str
    model: str
    ollama_url: str
    litellm_alias: str
    context_tokens: int
    keep_alive: str
    exclusive_group: str
    purpose: str = ""
    requires_target_paths: bool = False


def load_profiles(path: Path | str = DEFAULT_PROFILES) -> dict[str, ModelProfile]:
    raw = json.loads(Path(path).read_text(encoding="utf-8"))
    roles = raw.get("roles")
    if not isinstance(roles, dict):
        raise ValueError("profiles.json enthält kein roles-Objekt.")
    result: dict[str, ModelProfile] = {}
    for role, item in roles.items():
        if not isinstance(item, dict):
            raise ValueError(f"Ungültiges Profil für {role}.")
        result[role] = ModelProfile(
            role=role,
            model=str(item["model"]),
            ollama_url=str(item["ollama_url"]).rstrip("/"),
            litellm_alias=str(item["litellm_alias"]),
            context_tokens=int(item["context_tokens"]),
            keep_alive=str(item.get("keep_alive", "5m")),
            exclusive_group=str(item.get("exclusive_group", role)),
            purpose=str(item.get("purpose", "")),
            requires_target_paths=bool(item.get("requires_target_paths", False)),
        )
    return result


class OllamaClient:
    def __init__(self, base_url: str, timeout: int = 600) -> None:
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def _request(self, path: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        data = None if payload is None else json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(
            self.base_url + path,
            data=data,
            headers={"Content-Type": "application/json"},
            method="GET" if payload is None else "POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                body = response.read().decode("utf-8")
        except (OSError, urllib.error.URLError) as exc:
            raise RuntimeError(f"Ollama nicht erreichbar: {self.base_url}: {exc}") from exc
        return json.loads(body) if body else {}

    def running_models(self) -> list[dict[str, Any]]:
        body = self._request("/api/ps")
        models = body.get("models", [])
        return models if isinstance(models, list) else []

    def load(self, model: str, *, context_tokens: int, keep_alive: str) -> dict[str, Any]:
        return self._request(
            "/api/generate",
            {
                "model": model,
                "prompt": "",
                "stream": False,
                "keep_alive": keep_alive,
                "options": {"num_ctx": int(context_tokens)},
            },
        )

    def unload(self, model: str) -> dict[str, Any]:
        return self._request(
            "/api/generate",
            {
                "model": model,
                "prompt": "",
                "stream": False,
                "keep_alive": 0,
            },
        )


def _same_model(expected: str, running: dict[str, Any]) -> bool:
    candidates = {
        str(running.get("name", "")),
        str(running.get("model", "")),
    }
    if expected in candidates:
        return True
    expected_base = expected.removesuffix(":latest")
    return any(candidate.removesuffix(":latest") == expected_base for candidate in candidates if candidate)


class ModelManager:
    """Controls model residency without touching the frozen Agent Core."""

    def __init__(
        self,
        profiles: dict[str, ModelProfile] | None = None,
        *,
        client_factory: Callable[[str], OllamaClient] = OllamaClient,
    ) -> None:
        self.profiles = profiles or load_profiles()
        self.client_factory = client_factory

    def _profile(self, role: str) -> ModelProfile:
        key = str(role).strip().lower()
        if key not in self.profiles:
            raise ValueError(f"Unbekannte Modellrolle: {role}")
        return self.profiles[key]

    def _client(self, profile: ModelProfile) -> OllamaClient:
        return self.client_factory(profile.ollama_url)

    def _running(self, profile: ModelProfile) -> list[dict[str, Any]]:
        return self._client(profile).running_models()

    def prepare(self, role: str, *, wait_seconds: int = 120) -> dict[str, Any]:
        target = self._profile(role)
        client = self._client(target)
        running = client.running_models()

        unloaded: list[str] = []
        for other in self.profiles.values():
            if other.role == target.role:
                continue
            if other.ollama_url != target.ollama_url:
                continue
            if other.exclusive_group != target.exclusive_group:
                continue
            if any(_same_model(other.model, item) for item in running):
                client.unload(other.model)
                unloaded.append(other.model)

        running = client.running_models()
        current = next((item for item in running if _same_model(target.model, item)), None)
        if current is not None:
            loaded_ctx = int(current.get("context_length") or 0)
            if loaded_ctx and loaded_ctx != target.context_tokens:
                client.unload(target.model)
                current = None

        if current is None:
            client.load(
                target.model,
                context_tokens=target.context_tokens,
                keep_alive=target.keep_alive,
            )
        else:
            # Refresh idle lifetime without forcing a second model into memory.
            client.load(
                target.model,
                context_tokens=target.context_tokens,
                keep_alive=target.keep_alive,
            )

        deadline = time.monotonic() + max(1, int(wait_seconds))
        loaded: dict[str, Any] | None = None
        while time.monotonic() < deadline:
            for item in client.running_models():
                if _same_model(target.model, item):
                    loaded = item
                    break
            if loaded is not None:
                break
            time.sleep(1)

        if loaded is None:
            raise RuntimeError(f"Modell wurde nicht innerhalb von {wait_seconds}s sichtbar: {target.model}")

        return {
            "role": target.role,
            "model": target.model,
            "litellm_alias": target.litellm_alias,
            "context_tokens": target.context_tokens,
            "keep_alive": target.keep_alive,
            "unloaded": unloaded,
            "running": loaded,
        }

    def release(self, role: str) -> dict[str, Any]:
        profile = self._profile(role)
        client = self._client(profile)
        running = client.running_models()
        if not any(_same_model(profile.model, item) for item in running):
            return {"role": profile.role, "model": profile.model, "unloaded": False}
        client.unload(profile.model)
        return {"role": profile.role, "model": profile.model, "unloaded": True}

    def release_group(self, group: str) -> dict[str, Any]:
        released: list[str] = []
        for profile in self.profiles.values():
            if profile.exclusive_group != group:
                continue
            result = self.release(profile.role)
            if result["unloaded"]:
                released.append(profile.model)
        return {"group": group, "released": released}

    def status(self) -> dict[str, Any]:
        by_url: dict[str, Any] = {}
        for profile in self.profiles.values():
            if profile.ollama_url in by_url:
                continue
            by_url[profile.ollama_url] = self._client(profile).running_models()
        return {"servers": by_url}

    def profile_info(self, role: str) -> dict[str, Any]:
        return dataclasses.asdict(self._profile(role))


def main() -> int:
    parser = argparse.ArgumentParser(description="Hermclaw local model residency manager")
    parser.add_argument("--profiles", default=str(DEFAULT_PROFILES))
    sub = parser.add_subparsers(dest="command", required=True)

    p_prepare = sub.add_parser("prepare", help="Andere Modelle der Gruppe entladen und Zielmodell laden")
    p_prepare.add_argument("role", choices=["fast", "main", "heavy"])
    p_prepare.add_argument("--wait-seconds", type=int, default=120)

    p_release = sub.add_parser("release", help="Eine Modellrolle sofort entladen")
    p_release.add_argument("role", choices=["fast", "main", "heavy"])

    p_group = sub.add_parser("release-group", help="Alle geladenen Modelle einer Gruppe entladen")
    p_group.add_argument("group")

    sub.add_parser("status", help="Geladene Ollama-Modelle anzeigen")

    p_profile = sub.add_parser("profile", help="Profil einer Rolle anzeigen")
    p_profile.add_argument("role", choices=["fast", "main", "heavy"])

    args = parser.parse_args()
    manager = ModelManager(load_profiles(args.profiles))

    if args.command == "prepare":
        result = manager.prepare(args.role, wait_seconds=args.wait_seconds)
    elif args.command == "release":
        result = manager.release(args.role)
    elif args.command == "release-group":
        result = manager.release_group(args.group)
    elif args.command == "profile":
        result = manager.profile_info(args.role)
    else:
        result = manager.status()

    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import unittest

from model_runtime.router import route_task, validate_handoff


class RouterTests(unittest.TestCase):
    def test_discovery_starts_fast(self):
        self.assertEqual(route_task(stage="discovery").role, "fast")

    def test_main_requires_concrete_paths(self):
        self.assertEqual(
            route_task(stage="implementation", target_paths=["nav/settings_benutzer.php"]).role,
            "main",
        )
        self.assertEqual(route_task(stage="implementation").role, "fast")

    def test_repeated_failure_escalates_heavy(self):
        self.assertEqual(route_task(stage="hard-debug", failures=2).role, "heavy")

    def test_explicit_main_without_paths_is_rejected(self):
        with self.assertRaises(ValueError):
            route_task(explicit_role="main")

    def test_handoff_limits_scope(self):
        with self.assertRaises(ValueError):
            validate_handoff(
                "main",
                {"task": "x", "target_paths": [f"f{i}.php" for i in range(13)]},
            )


if __name__ == "__main__":
    unittest.main()

import unittest

from model_runtime.model_manager import ModelManager, ModelProfile


class FakeClient:
    def __init__(self, url, state, calls):
        self.url = url
        self.state = state
        self.calls = calls

    def running_models(self):
        return [dict(item) for item in self.state.setdefault(self.url, [])]

    def unload(self, model):
        self.calls.append(("unload", self.url, model))
        self.state[self.url] = [
            item for item in self.state.setdefault(self.url, [])
            if item.get("name") != model and item.get("model") != model
        ]
        return {}

    def load(self, model, *, context_tokens, keep_alive):
        self.calls.append(("load", self.url, model, context_tokens, keep_alive))
        self.state[self.url] = [
            item for item in self.state.setdefault(self.url, [])
            if item.get("name") != model and item.get("model") != model
        ]
        self.state[self.url].append(
            {"name": model, "model": model, "context_length": context_tokens}
        )
        return {}


class ManagerTests(unittest.TestCase):
    def make_manager(self):
        profiles = {
            "fast": ModelProfile(
                "fast", "fast:14b", "http://222", "fast", 16384, "10m", "fast-222"
            ),
            "main": ModelProfile(
                "main", "main:30b", "http://224", "main", 24576, "5m", "large-224"
            ),
            "heavy": ModelProfile(
                "heavy", "heavy:27b", "http://224", "heavy", 24576, "5m", "large-224"
            ),
        }
        state = {
            "http://222": [{"name": "fast:14b", "model": "fast:14b", "context_length": 16384}],
            "http://224": [{"name": "main:30b", "model": "main:30b", "context_length": 24576}],
        }
        calls = []

        def factory(url):
            return FakeClient(url, state, calls)

        return ModelManager(profiles, client_factory=factory), state, calls

    def test_switch_main_to_heavy_unloads_only_same_pool(self):
        manager, state, calls = self.make_manager()
        result = manager.prepare("heavy", wait_seconds=1)

        self.assertEqual(result["role"], "heavy")
        self.assertIn(("unload", "http://224", "main:30b"), calls)
        self.assertIn(("load", "http://224", "heavy:27b", 24576, "5m"), calls)
        self.assertTrue(any(item["name"] == "fast:14b" for item in state["http://222"]))
        self.assertFalse(any(call[:3] == ("unload", "http://222", "fast:14b") for call in calls))

    def test_release_is_immediate(self):
        manager, state, calls = self.make_manager()
        result = manager.release("main")
        self.assertTrue(result["unloaded"])
        self.assertIn(("unload", "http://224", "main:30b"), calls)


if __name__ == "__main__":
    unittest.main()
